#!/usr/bin/env python3
"""microbiome/cooccurrence_network — auto-generated run.py (archetype=microbiome_pipeline).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "microbiome_pipeline"
BRAIN = "microbiome"
SKILL = "cooccurrence_network"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'cooccurrence_network', 'n_samples': 0, 'taxonomy_table': '', 'diversity_metrics': {'shannon': 0.0, 'observed_otus': 0}, 'diagnostics': {'brain': 'microbiome', 'archetype': 'microbiome_pipeline'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Taxa 共现网络:基于 abundance matrix 算 Pearson 相关 + Bonferroni 过滤。
    host_env=praxis-microbiome(无专门 SparCC,用 scipy.stats.pearsonr)。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    abun = payload.get("abundance_csv")
    pval_cutoff = float(payload.get("pval_cutoff", 0.01))
    cor_cutoff = float(payload.get("cor_cutoff", 0.5))
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="cooc_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "scipy.pearsonr", "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_samples": 0, "taxonomy_table": "",
                "diversity_metrics": {"shannon": 0.0, "observed_otus": 0},
                "diagnostics": {**diagnostics, "dry": True}}
    if not abun or not _os.path.isfile(abun):
        return {"ok": False, "error": "需要 abundance_csv (rows=samples, cols=taxa)",
                "diagnostics": diagnostics}
    _os.makedirs(out_dir, exist_ok=True)
    edges_csv = _os.path.join(out_dir, "edges.csv")
    script = (
        "import json, sys, csv\n"
        "import pandas as pd\n"
        "from scipy.stats import pearsonr\n"
        f"abun = pd.read_csv({abun!r}, index_col=0)\n"
        "edges = []\n"
        "cols = abun.columns.tolist()\n"
        "for i in range(len(cols)):\n"
        "    for j in range(i+1, len(cols)):\n"
        "        try:\n"
        "            r_, p_ = pearsonr(abun[cols[i]], abun[cols[j]])\n"
        f"            if p_ < {pval_cutoff} and abs(r_) > {cor_cutoff}:\n"
        "                edges.append({'a': cols[i], 'b': cols[j], 'r': float(r_), 'p': float(p_)})\n"
        "        except Exception: pass\n"
        "n_bonferroni = sum(1 for e in edges if e['p'] * (len(cols)*(len(cols)-1)/2) < 0.05)\n"
        f"with open({edges_csv!r}, 'w') as fh:\n"
        "    w = csv.DictWriter(fh, fieldnames=['a','b','r','p']); w.writeheader()\n"
        "    for e in edges: w.writerow(e)\n"
        f"json.dump({{'edges_csv': {edges_csv!r}, 'n_edges': len(edges), 'n_taxa': len(cols),\n"
        "             'n_bonferroni_significant': n_bonferroni}}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "cooccurrence 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, "n_samples": parsed.get("n_taxa", 0),
            "taxonomy_table": parsed.get("edges_csv", ""),
            "diversity_metrics": {"shannon": 0.0, "observed_otus": parsed.get("n_edges", 0)},
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, **parsed}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
